<?php
if (!defined('ABSPATH')) exit;
class CC_Moderation {
 public static function init(){add_action('add_meta_boxes',array(__CLASS__,'box'));add_action('save_post_cc_submission',array(__CLASS__,'save'),10,2);}
 public static function box(){add_meta_box('cc_moderation','بررسی مشارکت',array(__CLASS__,'render'),'cc_submission','side','high');}
 public static function render($post){wp_nonce_field('cc_moderate','cc_moderate_nonce');$city=(int)get_post_meta($post->ID,'cc_city_id',true);$img=(int)get_post_meta($post->ID,'cc_image_id',true);echo '<p><strong>شهر:</strong> '.esc_html(get_the_title($city)).'</p><p><strong>نوع:</strong> '.esc_html(get_post_meta($post->ID,'cc_type',true)).'</p>';if($img)echo wp_get_attachment_image($img,'medium');echo '<p><label for="cc_review_note">یادداشت بررسی</label><textarea name="cc_review_note" id="cc_review_note" style="width:100%">'.esc_textarea(get_post_meta($post->ID,'cc_review_note',true)).'</textarea></p><p><button class="button button-primary" name="cc_action" value="approve">تأیید و انتشار</button> <button class="button" name="cc_action" value="reject">رد مشارکت</button></p>' ;}
 public static function save($id,$post){if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)return;if(!current_user_can('edit_post',$id)||!isset($_POST['cc_moderate_nonce'])||!wp_verify_nonce($_POST['cc_moderate_nonce'],'cc_moderate'))return;if(isset($_POST['cc_review_note']))update_post_meta($id,'cc_review_note',sanitize_textarea_field($_POST['cc_review_note']));$action=sanitize_key($_POST['cc_action']??'');if($action==='approve')wp_update_post(array('ID'=>$id,'post_status'=>'publish'));if($action==='reject')wp_update_post(array('ID'=>$id,'post_status'=>'rejected'));}
}
